package com.fasterxml.jackson.databind.ser;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializationConfig;
import com.fasterxml.jackson.databind.annotation.JsonSerialize;
import com.fasterxml.jackson.databind.cfg.SerializerFactoryConfig;
import com.fasterxml.jackson.databind.ext.OptionalHandlerFactory;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.NamedType;
import com.fasterxml.jackson.databind.jsontype.TypeResolverBuilder;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.ser.BeanDescription;
import com.fasterxml.jackson.databind.ser.impl.*;
import com.fasterxml.jackson.databind.ser.std.*;
import com.fasterxml.jackson.databind.ser.std.DateSerializer;
import com.fasterxml.jackson.databind.ser.std.NumberSerializer;
import com.fasterxml.jackson.databind.ser.std.ToStringSerializer;
import com.fasterxml.jackson.databind.type.*;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.*;
import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.charset.Charset;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.Map;
import java.util.TimeZone;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class BasicSerializerFactory_findSerializerByPrimaryType_TriageGen2Test {

    private TestableBasicSerializerFactory factory;
    private SerializerProvider prov;
    private BeanDescription beanDesc;
    private SerializationConfig config;
    private TypeFactory typeFactory;

    // Subclass to expose protected method for testing
    private static class TestableBasicSerializerFactory extends BasicSerializerFactory {
        protected TestableBasicSerializerFactory() {
            super(null);
        }

        @Override
        protected Iterable<Serializers> customSerializers() {
            return null;
        }

        @Override
        public JsonSerializer<Object> createSerializer(SerializerProvider prov, JavaType type) throws JsonMappingException {
            return null;
        }

        // Expose the protected method
        public JsonSerializer<?> publicFindSerializerByPrimaryType(SerializerProvider prov, JavaType type, BeanDescription beanDesc, boolean staticTyping) throws JsonMappingException {
            return findSerializerByPrimaryType(prov, type, beanDesc, staticTyping);
        }

        // Mockable overrides for internal calls
        protected JsonSerializer<?> findOptionalStdSerializer(SerializerProvider prov, JavaType type, BeanDescription beanDesc, boolean staticTyping) throws JsonMappingException {
            return null;
        }

        protected JsonSerializer<?> buildMapEntrySerializer(SerializationConfig config, JavaType type, BeanDescription beanDesc, boolean staticTyping, JavaType kt, JavaType vt) throws JsonMappingException {
            return null;
        }

        protected JsonSerializer<?> buildEnumSerializer(SerializationConfig config, JavaType type, BeanDescription beanDesc) throws JsonMappingException {
            return null;
        }
    }

    @Before
    public void setUp() {
        factory = spy(new TestableBasicSerializerFactory());
        prov = mock(SerializerProvider.class);
        beanDesc = mock(BeanDescription.class);
        config = mock(SerializationConfig.class);
        typeFactory = TypeFactory.defaultInstance();
        when(prov.getConfig()).thenReturn(config);
    }

    @Test
    public void testFindOptionalStdSerializerFirst() throws JsonMappingException {
        JavaType type = typeFactory.constructType(String.class);
        JsonSerializer<?> mockSer = mock(JsonSerializer.class);
        doReturn(mockSer).when(factory).findOptionalStdSerializer(any(), any(), any(), anyBoolean());

        JsonSerializer<?> result = factory.publicFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(mockSer, result);
    }

    @Test
    public void testCalendarSerializer() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Calendar.class);
        JsonSerializer<?> result = factory.publicFindSerializerByPrimaryType(prov, type, beanDesc, false);
        // Note: CalendarSerializer.instance check is internal to Jackson, 
        // but we verify it doesn't return null or the optional one
        assertNotNull(result);
    }

    @Test
    public void testDateSerializer() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Date.class);
        JsonSerializer<?> result = factory.publicFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(DateSerializer.instance, result);
    }

    @Test
    public void testMapEntrySerializer() throws JsonMappingException {
        // Map.Entry<String, Integer>
        JavaType type = typeFactory.constructMapType(Map.class, String.class, Integer.class);
        // We need to simulate the containedType logic
        // Since we use real TypeFactory, kt and vt will be populated

        JsonSerializer<?> mockSer = mock(JsonSerializer.class);
        doReturn(mockSer).when(factory).buildMapEntrySerializer(any(), any(), any(), anyBoolean(), any(), any());

        JsonSerializer<?> result = factory.publicFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(mockSer, result);
    }

    @Test
    public void testMapEntrySerializerWithNullContainedTypes() throws JsonMappingException {
        // Simulate a case where contained types might be null if manually constructed via mock or edge cases
        JavaType mockType = mock(JavaType.class);
        when(mockType.getRawClass()).thenReturn(Map.Entry.class);
        when(mockType.containedType(0)).thenReturn(null);
        when(mockType.containedType(1)).thenReturn(null);

        JsonSerializer<?> mockSer = mock(JsonSerializer.class);
        doReturn(mockSer).when(factory).buildMapEntrySerializer(any(), any(), any(), anyBoolean(), any(), any());

        JsonSerializer<?> result = factory.publicFindSerializerByPrimaryType(prov, mockType, beanDesc, false);
        assertEquals(mockSer, result);
    }

    @Test
    public void testByteBufferSerializer() throws JsonMappingException {
        JavaType type = typeFactory.constructType(ByteBuffer.class);
        JsonSerializer<?> result = factory.publicFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNotNull(result);
        assertTrue(result.getClass().getSimpleName().contains("ByteBufferSerializer"));
    }

    @Test
    public void testInetAddressSerializer() throws JsonMappingException {
        JavaType type = typeFactory.constructType(InetAddress.class);
        JsonSerializer<?> result = factory.publicFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNotNull(result);
    }

    @Test
    public void testInetSocketAddressSerializer() throws JsonMappingException {
        JavaType type = typeFactory.constructType(InetSocketAddress.class);
        JsonSerializer<?> result = factory.publicFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNotNull(result);
    }

    @Test
    public void testTimeZoneSerializer() throws JsonMappingException {
        JavaType type = typeFactory.constructType(TimeZone.class);
        JsonSerializer<?> result = factory.publicFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNotNull(result);
    }

    @Test
    public void testCharsetSerializer() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Charset.class);
        JsonSerializer<?> result = factory.publicFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(ToStringSerializer.instance, result);
    }

    @Test
    public void testNumberSerializerDefault() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Integer.class);
        when(beanDesc.findExpectedFormat(null)).thenReturn(null);

        JsonSerializer<?> result = factory.publicFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(NumberSerializer.instance, result);
    }

    @Test
    public void testNumberSerializerWithFormatString() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Integer.class);
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(beanDesc.findExpectedFormat(null)).thenReturn(format);

        JsonSerializer<?> result = factory.publicFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(ToStringSerializer.instance, result);
    }

    @Test
    public void testNumberSerializerWithFormatObjectOrArray() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Integer.class);

        // Test OBJECT
        JsonFormat.Value formatObj = mock(JsonFormat.Value.class);
        when(formatObj.getShape()).thenReturn(JsonFormat.Shape.OBJECT);
        when(beanDesc.findExpectedFormat(null)).thenReturn(formatObj);
        assertNull(factory.publicFindSerializerByPrimaryType(prov, type, beanDesc, false));

        // Test ARRAY
        JsonFormat.Value formatArr = mock(JsonFormat.Value.class);
        when(formatArr.getShape()).thenReturn(JsonFormat.Shape.ARRAY);
        when(beanDesc.findExpectedFormat(null)).thenReturn(formatArr);
        assertNull(factory.publicFindSerializerByPrimaryType(prov, type, beanDesc, false));
    }

    @Test
    public void testEnumSerializer() throws JsonMappingException {
        enum TestEnum { A, B }
        JavaType type = typeFactory.constructType(TestEnum.class);
        JsonSerializer<?> mockSer = mock(JsonSerializer.class);
        doReturn(mockSer).when(factory).buildEnumSerializer(any(), any(), any());

        JsonSerializer<?> result = factory.publicFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(mockSer, result);
    }

    @Test
    public void testUnknownTypeReturnsNull() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Object.class);
        JsonSerializer<?> result = factory.publicFindSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNull(result);
    }
}
